import 'package:flutter/material.dart'; 
// The main function that starts the Flutter application.
void main() => runApp(MyApp()); 
// This is the root widget of the application. It's a StatelessWidget because its configuration is immutable.
class MyApp extends StatelessWidget { 
	@override 
	// The build method describes the part of the user interface represented by this widget.
	Widget build(BuildContext context) { 
		// MaterialApp is a widget that wraps a number of widgets that are commonly required for an application implementing Material Design.
		return MaterialApp(
			// The home property defines the widget that is displayed as the homepage of the application.
			home: Scaffold(
				// Scaffold implements the basic material design visual layout structure.
				appBar: AppBar(
					// AppBar is a horizontal bar typically shown at the top of the Scaffold.
					title: Text("Flutter Form Demo"), // The title displayed in the AppBar.
				),
				// The body property holds the main content of the Scaffold, here it's our custom form.
				body: MyForm(),
			),
		);
	}
}

// StatefulWidget is a widget that has mutable state that can change over its lifetime.
class MyForm extends StatefulWidget { 
	@override 
	// Creates the mutable state for this widget.
	_MyFormState createState() => _MyFormState();
}

// This is the state class for the MyForm widget.
class _MyFormState extends State<MyForm> { 
	// Key to identify and control the Form widget. It allows us to validate, reset, or save the form.
	final _formKey = GlobalKey<FormState>();

	// Variables to store the user's input for email and password.
	String _email = "";
	String _password = "";

	@override 
	// The build method describes the part of the user interface represented by this widget.
	Widget build(BuildContext context) { 
		// Padding widget adds empty space around its child.
		return Padding(
			padding: EdgeInsets.all(16.0), // Adds 16 logical pixels of padding on all sides.
			// Form is a container for grouping together several form field widgets.
			child: Form(
				key: _formKey, // Assigns the global key to this Form widget.
				// Column arranges its children in a vertical line.
				child: Column(
					children: [
						// TextFormField is a Material Design text field with built-in validation and decoration.
						TextFormField(
							// InputDecoration provides visual cues for the text field (label, hint, border).
							decoration: InputDecoration(
								labelText: "Email", // The label text that appears above the input field.
								hintText: "Enter your email", // The hint text displayed when the input field is empty.
								border: OutlineInputBorder(), // Creates a rounded rectangular border around the input field.
							),
							// Validator function that is called on form submission to check the validity of the input.
							validator: (value) {
								if (value == null || value.isEmpty) { // Checks if the input value is null or empty.
									return "Please enter an email"; // Returns an error message if the condition is true.
								}
								if (!value.contains("@")) { // Checks if the input value contains the "@" symbol for basic email validation.
									return "Enter a valid email"; // Returns an error message if the condition is true.
								}
								return null; // Returns null if the input is valid (no error).
							},
							// Called when the form field changes and is saved. Here, we store the entered email.
							onSaved: (value) => _email = value!,
						),

						SizedBox(height: 20), // Adds a vertical space of 20 logical pixels between the form fields.

						// Another TextFormField for the password input.
						TextFormField(
							obscureText: true, // Hides the entered text, commonly used for passwords.
							decoration: InputDecoration(
								labelText: "Password", // The label text for the password field.
								hintText: "Enter your password", // The hint text for the password field.
								border: OutlineInputBorder(), // Border for the password field.
							),
							// Validator for the password field.
							validator: (value) {
								if (value == null || value.isEmpty) { // Checks if the password field is empty.
									return "Please enter a password"; // Error message for an empty password.
								}
								if (value.length < 6) { // Checks if the password length is less than 6 characters.
									return "Password must be at least 6 characters"; // Error message for a short password.
								}
								return null; // No error for a valid password.
							},
							// Called when the password field is saved.
							onSaved: (value) => _password = value!,
						),

						SizedBox(height: 20), // Adds spacing before the submit button.

						// ElevatedButton is a Material Design elevated button.
						ElevatedButton(
							// Called when the button is pressed.
							onPressed: () {
								// Validates the form using the global key.
								if (_formKey.currentState!.validate()) {
									_formKey.currentState!.save(); // Saves the form data, triggering the onSaved callbacks of the fields.
									// Shows a SnackBar to provide feedback to the user.
									ScaffoldMessenger.of(context).showSnackBar(
										SnackBar(content: Text("Form Submitted!")), // The content of the SnackBar.
									);
									// Prints the submitted email and password to the console.
									print("Email: $_email, Password: $_password");
								}
							},
							child: Text("Submit"), // The text displayed on the button.
						),
					],
				),
			),
		);
	}
}

